  Mail_122567_Desc = {
    Text = "Sevgili Koruyucu:\n“\"Sis\"le Örtülü Ayin” Etkinliği Sona Erdi. Kalan \"Sis\" Görüşü, \"Sis\" Rüyası ve \"Sis\" Özü, 1’e karşılık “Gül Senedi *40” oranıyla dönüştürülecek. Lütfen ödüllerini kontrol etmeyi unutma."
