  Mail_134024_Desc = {
    Text = "Sayın Koruyucu:\n\"Günlük Görev\" kaldırılmıştır. Kalan \"Vekâlet Sertifikaları\" sertifika başına 10000 × \"Altın Gül\" oranında dönüştürülecektir. Lütfen ödüllerinizi kontrol etmeyi unutmayın."
